        return out
    rmin, rmax = min(r for r, c in points), max(r for r, c in points)
    cmin, cmax = min(c for r, c in points), max(c for r, c in points)
    row_counts = [sum(grid[r][c] != background for c in range(w)) for r in range(h)]
    col_counts = [sum(grid[r][c] != background for r in range(h)) for c in range(w)]
    dense_rows = {r for r in range(h) if row_counts[r] >= 3}
    dense_cols = {c for c in range(w) if col_counts[c] >= 3}

    # Complete horizontal strokes across the overall pattern span.
    for r in dense_rows:
        for c in range(cmin, cmax + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Complete vertical strokes that have markers outside horizontal stroke rows.
    for c in dense_cols:
        rows = [r for r in range(h) if grid[r][c] != background]
        if not any(r not in dense_rows for r in rows):
            continue
        lo, hi = min(rows), max(rows)
        # Outer side strokes meet the top/bottom dense horizontal strokes.
        if c in (cmin, cmax):
            if rmin in dense_rows:
                lo = min(lo, rmin)
            if rmax in dense_rows:
                hi = max(hi, rmax)
        for r in range(lo, hi + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Fill a two-marker segment when one endpoint is not already on a
    # perpendicular dense stroke (a lone alignment is not a crossing).
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != background]
        if len(cols) == 2 and not all(c in dense_cols for c in cols):
            for c in range(cols[0] + 1, cols[1]):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
